module Moderate
  class QuizzesController < BaseController
    before_action :set_quiz, only: [ :show, :edit, :update, :destroy, :export ]

    def index
      @quizzes = Quiz.order(:id).includes(:questions)
    end

    def show
      @questions = @quiz.questions.includes(:options)
    end

    def new
      @quiz = Quiz.new
    end

    def create
      @quiz = Quiz.new(quiz_params)
      if @quiz.save
        redirect_to moderate_quiz_path(@quiz)
      else
        render :new, status: :unprocessable_entity
      end
    end

    def edit
    end

    def update
      if @quiz.update(quiz_params)
        redirect_to moderate_quiz_path(@quiz)
      else
        render :edit, status: :unprocessable_entity
      end
    end

    def destroy
      @quiz.destroy!
      redirect_to moderate_root_path
    end

    def export
      @json = QuizExport.json_for(@quiz)
    end

    private
      def set_quiz
        @quiz = Quiz.find(params[:id])
      end

      def quiz_params
        params.require(:quiz).permit(:title)
      end
  end
end
